-- paper_analyzer backup 2026-10-06T11:06:27.106Z
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
SET SQL_MODE='NO_AUTO_VALUE_ON_ZERO';

-- answers
DROP TABLE IF EXISTS `answers`;
CREATE TABLE `answers` (
  `question_id` int unsigned NOT NULL,
  `correct_option` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MCQ letter',
  `text` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'Mark scheme points, Markdown + LaTeX',
  `source` enum('MARK_SCHEME','MANUAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MARK_SCHEME',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`),
  FULLTEXT KEY `ft_answers_text` (`text`),
  CONSTRAINT `answers_question_id_foreign` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- audit_logs
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `action` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PAPER_UPLOADED, QUESTION_EDITED, PAPER_PUBLISHED ...',
  `entity` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'paper, question ...',
  `entity_id` int unsigned DEFAULT NULL,
  `data` json DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `audit_logs_user_id_foreign` (`user_id`),
  KEY `audit_logs_entity_entity_id_index` (`entity`,`entity_id`),
  KEY `audit_logs_created_at_index` (`created_at`),
  CONSTRAINT `audit_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- boards
DROP TABLE IF EXISTS `boards`;
CREATE TABLE `boards` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CIE, EDEXCEL, AQA, OCR, IB, CBSE, MOE',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Cambridge International, Pearson Edexcel',
  `short_name` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `boards_code_unique` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- components
DROP TABLE IF EXISTS `components`;
CREATE TABLE `components` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` int unsigned NOT NULL,
  `number` smallint NOT NULL COMMENT 'Paper number: 1, 2, 3 ...',
  `name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Multiple Choice, Core Physics I',
  `style` enum('MCQ','THEORY','PRACTICAL','MIXED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MIXED',
  `total_marks` smallint DEFAULT NULL,
  `duration_min` smallint DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `components_subject_id_number_unique` (`subject_id`,`number`),
  CONSTRAINT `components_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- curriculums
DROP TABLE IF EXISTS `curriculums`;
CREATE TABLE `curriculums` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `board_id` int unsigned NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CIE AS & A Level, Edexcel AS Level',
  `level` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AS, A Level, IGCSE, Grade 10 ...',
  `sort_order` smallint NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `curriculums_board_id_name_unique` (`board_id`,`name`),
  CONSTRAINT `curriculums_board_id_foreign` FOREIGN KEY (`board_id`) REFERENCES `boards` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- knex_migrations
DROP TABLE IF EXISTS `knex_migrations`;
CREATE TABLE `knex_migrations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `batch` int DEFAULT NULL,
  `migration_time` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- knex_migrations_lock
DROP TABLE IF EXISTS `knex_migrations_lock`;
CREATE TABLE `knex_migrations_lock` (
  `index` int unsigned NOT NULL AUTO_INCREMENT,
  `is_locked` int DEFAULT NULL,
  PRIMARY KEY (`index`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- papers
DROP TABLE IF EXISTS `papers`;
CREATE TABLE `papers` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '8PH0_s16_01 - also the storage folder name',
  `subject_id` int unsigned NOT NULL,
  `component_id` int unsigned DEFAULT NULL,
  `year` smallint NOT NULL,
  `season_code` varchar(1) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paper_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'As printed: 11, 01',
  `variant` tinyint DEFAULT NULL COMMENT 'Cambridge variant digit',
  `component_name` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Paper title printed on the cover',
  `qp_file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Original file name',
  `ms_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qp_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Storage key, e.g. papers/8PH0_s16_01/qp.pdf',
  `ms_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qp_page_count` smallint DEFAULT NULL,
  `ms_page_count` smallint DEFAULT NULL,
  `status` enum('UPLOADED','PROCESSING','IN_REVIEW','PUBLISHED','FAILED','ARCHIVED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOADED',
  `ai_provider` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ai_model` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `published_by` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `papers_slug_unique` (`slug`),
  UNIQUE KEY `papers_subject_id_year_season_code_paper_code_unique` (`subject_id`,`year`,`season_code`,`paper_code`),
  KEY `papers_component_id_foreign` (`component_id`),
  KEY `papers_season_code_foreign` (`season_code`),
  KEY `papers_published_by_foreign` (`published_by`),
  KEY `papers_created_by_foreign` (`created_by`),
  KEY `papers_status_index` (`status`),
  KEY `papers_subject_id_status_year_index` (`subject_id`,`status`,`year`),
  CONSTRAINT `papers_component_id_foreign` FOREIGN KEY (`component_id`) REFERENCES `components` (`id`) ON DELETE SET NULL,
  CONSTRAINT `papers_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `papers_published_by_foreign` FOREIGN KEY (`published_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `papers_season_code_foreign` FOREIGN KEY (`season_code`) REFERENCES `seasons` (`code`),
  CONSTRAINT `papers_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- processing_jobs
DROP TABLE IF EXISTS `processing_jobs`;
CREATE TABLE `processing_jobs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `paper_id` int unsigned NOT NULL,
  `state` enum('QUEUED','RENDERING','EXTRACTING','MARK_SCHEME','DONE','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'QUEUED',
  `progress` tinyint unsigned NOT NULL DEFAULT '0',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pages_total` smallint NOT NULL DEFAULT '0',
  `pages_done` smallint NOT NULL DEFAULT '0',
  `questions_found` smallint NOT NULL DEFAULT '0',
  `failed_pages` json DEFAULT NULL COMMENT '{ qp: [5, 9], ms: [3] }',
  `error` text COLLATE utf8mb4_unicode_ci,
  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `processing_jobs_paper_id_created_at_index` (`paper_id`,`created_at`),
  CONSTRAINT `processing_jobs_paper_id_foreign` FOREIGN KEY (`paper_id`) REFERENCES `papers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- question_embeddings
DROP TABLE IF EXISTS `question_embeddings`;
CREATE TABLE `question_embeddings` (
  `question_id` int unsigned NOT NULL,
  `model` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. bge-small-en-v1.5 - vectors from different models are not comparable',
  `dimensions` smallint NOT NULL COMMENT 'e.g. 384',
  `embedding` blob NOT NULL COMMENT 'float32 little-endian, dimensions x 4 bytes',
  `text_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sha256 of the embedded text - re-embed only when it changes',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`question_id`),
  KEY `question_embeddings_model_index` (`model`),
  CONSTRAINT `question_embeddings_question_id_foreign` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- question_images
DROP TABLE IF EXISTS `question_images`;
CREATE TABLE `question_images` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `question_id` int unsigned NOT NULL,
  `kind` enum('QUESTION','ANSWER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'QUESTION',
  `source` enum('QP','MS') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'QP' COMMENT 'Which PDF the crop comes from',
  `page` smallint NOT NULL,
  `box` json NOT NULL COMMENT '{x0,y0,x1,y1} as 0..1 fractions of the page',
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Cropped WebP storage key; NULL = crop on the fly',
  `sort_order` smallint NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `question_images_question_id_kind_sort_order_index` (`question_id`,`kind`,`sort_order`),
  CONSTRAINT `question_images_question_id_foreign` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=347 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- question_keywords
DROP TABLE IF EXISTS `question_keywords`;
CREATE TABLE `question_keywords` (
  `question_id` int unsigned NOT NULL,
  `keyword` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`question_id`,`keyword`),
  KEY `question_keywords_keyword_index` (`keyword`),
  CONSTRAINT `question_keywords_question_id_foreign` FOREIGN KEY (`question_id`) REFERENCES `questions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- questions
DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `paper_id` int unsigned NOT NULL,
  `subject_id` int unsigned NOT NULL COMMENT 'Copied from paper for fast filtering',
  `number` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'As printed: 1, 3(b)(ii)',
  `sort_order` smallint NOT NULL DEFAULT '0',
  `type` enum('MCQ','THEORY','STRUCTURED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `marks` smallint DEFAULT NULL,
  `text` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Markdown + LaTeX ($...$)',
  `options` json DEFAULT NULL COMMENT 'MCQ: [{label:"A", text:"..."}]',
  `topic_id` int unsigned DEFAULT NULL,
  `subtopic_id` int unsigned DEFAULT NULL,
  `subtopic_label` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI subtopic text when no subtopic row matches',
  `difficulty` enum('EASY','MEDIUM','HARD') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM',
  `page` smallint NOT NULL COMMENT 'First page in the question paper',
  `pages` json DEFAULT NULL COMMENT 'All pages, e.g. [7, 8]',
  `confidence` decimal(3,2) DEFAULT NULL COMMENT 'AI confidence 0..1',
  `status` enum('DRAFT','VERIFIED','PUBLISHED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `verified_by` int unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL,
  `edited_at` timestamp NULL DEFAULT NULL,
  `similar_ids` json DEFAULT NULL COMMENT 'Pre-computed similar question ids, best first',
  `similar_updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `questions_paper_id_number_unique` (`paper_id`,`number`),
  KEY `questions_subtopic_id_foreign` (`subtopic_id`),
  KEY `questions_verified_by_foreign` (`verified_by`),
  KEY `questions_subject_id_status_index` (`subject_id`,`status`),
  KEY `questions_topic_id_status_index` (`topic_id`,`status`),
  KEY `questions_difficulty_index` (`difficulty`),
  KEY `questions_paper_id_deleted_at_index` (`paper_id`,`deleted_at`),
  FULLTEXT KEY `ft_questions_text` (`text`),
  CONSTRAINT `questions_paper_id_foreign` FOREIGN KEY (`paper_id`) REFERENCES `papers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `questions_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`),
  CONSTRAINT `questions_subtopic_id_foreign` FOREIGN KEY (`subtopic_id`) REFERENCES `topics` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_topic_id_foreign` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE SET NULL,
  CONSTRAINT `questions_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=647 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- seasons
DROP TABLE IF EXISTS `seasons`;
CREATE TABLE `seasons` (
  `code` varchar(1) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'j, m, s, w',
  `name` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'January, Feb/March, May/June, Oct/Nov',
  `sort_order` smallint NOT NULL,
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- subjects
DROP TABLE IF EXISTS `subjects`;
CREATE TABLE `subjects` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `curriculum_id` int unsigned NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '9702, 8PH0, WPH11',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Physics',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `subjects_curriculum_id_code_unique` (`curriculum_id`,`code`),
  KEY `subjects_code_index` (`code`),
  CONSTRAINT `subjects_curriculum_id_foreign` FOREIGN KEY (`curriculum_id`) REFERENCES `curriculums` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- topics
DROP TABLE IF EXISTS `topics`;
CREATE TABLE `topics` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `subject_id` int unsigned NOT NULL,
  `parent_id` int unsigned DEFAULT NULL COMMENT 'NULL = topic, else subtopic',
  `code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Syllabus number, e.g. 3 or 3.2',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source` enum('SYLLABUS','AI','MANUAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SYLLABUS' COMMENT 'AI = created from extraction, needs review',
  `sort_order` smallint NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `topics_subject_id_parent_id_name_unique` (`subject_id`,`parent_id`,`name`),
  KEY `topics_parent_id_foreign` (`parent_id`),
  KEY `topics_subject_id_code_index` (`subject_id`,`code`),
  CONSTRAINT `topics_parent_id_foreign` FOREIGN KEY (`parent_id`) REFERENCES `topics` (`id`) ON DELETE CASCADE,
  CONSTRAINT `topics_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('SUPER_ADMIN','ADMIN','TEACHER','STUDENT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STUDENT',
  `status` enum('ACTIVE','INVITED','DISABLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `last_login_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;
SET UNIQUE_CHECKS=1;
